shell_commands:
python3 - <<'EOF'
p='src/orchestration/tools/registry.ts'
s=open(p).read()
s=s.replace("import {Ajv, type ValidateFunction} from 'ajv';\n","import ajvExports from 'ajv';\n")
s=s.replace("""interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: ValidateFunction;
}

const ajv = new Ajv({strict: false, validateFormats: false});
""","""// The slice of ajv this registry uses, typed locally so it holds across ajv majors: 8 names an
// error's location `instancePath` and exports the class as `.default`, 6 says `dataPath` and does not.
interface SchemaError {
  instancePath?: string;
  dataPath?: string;
  keyword: string;
  message?: string;
}

interface ValidateFunction {
  (data: unknown): boolean;
  errors?: SchemaError[] | null;
}

type SchemaCompilerClass = new (options: Record<string, unknown>) => {compile(schema: object): ValidateFunction};

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: ValidateFunction;
}

const ajvModule = ajvExports as unknown as SchemaCompilerClass & {default?: SchemaCompilerClass};
const SchemaCompiler = ajvModule.default ?? ajvModule;
const ajv = new SchemaCompiler({strict: false, validateFormats: false});
""")
s=s.replace("error => `${error.instancePath || '(input)'} ${error.message ?? error.keyword}`","error => `${error.instancePath || error.dataPath || '(input)'} ${error.message ?? error.keyword}`")
open(p,'w').write(s)

p='src/orchestration/tools/registry.test.ts'
s=open(p).read()
old="""    expect(executor).not.toHaveBeenCalled();
    expect(result).toMatch(/location.*required|required.*location/i);
"""
new="""    expect({result, calls: executor.mock.calls}).toEqual({result: expect.stringMatching(/required.*location/i), calls: []});
"""
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
EOF
grep -n inputSchema src/types/ai.ts

node --input-type=module -e "
import m from './node_modules/eslint/node_modules/ajv/lib/ajv.js';
const C = m.default ?? m; const a = new C({strict:false, validateFormats:false});
const v = a.compile({type:'object',required:['location'],properties:{location:{type:'string'}}});
console.log(v({}), JSON.stringify(v.errors.map(e=>[e.dataPath,e.message])));
v({location:3}); console.log(JSON.stringify(v.errors.map(e=>[e.dataPath,e.message])));
try{a.compile({type:'object',required:'location'})}catch(e){console.log('throws', e.message)}"
